/*
 * ReLoop simulated delivery tracking — demo page (no build step, no framework).
 * Talks to repair-service's /api/tracking API on the same origin and draws the route with Leaflet + OpenStreetMap.
 * Everything shown is SIMULATED: predefined Gujarat demo locations and positions generated by ReLoop.
 */
(function () {
  'use strict';

  var API = new URL('api/tracking/', document.baseURI).toString();
  var STORAGE = window.sessionStorage;
  var $ = function (id) { return document.getElementById(id); };

  var state = { trackingNumber: null, delivery: null, timer: null, fitted: null, markerPos: null };
  var map = null;
  var layers = {};

  /* ───────────── tokens / viewer ───────────── */

  function viewer() {
    var checked = document.querySelector('input[name=viewer]:checked');
    return checked ? checked.value : 'A';
  }

  function token() {
    var raw = (viewer() === 'A' ? $('tokenA') : $('tokenB')).value.trim();
    return raw.replace(/^Bearer\s+/i, '');
  }

  function decodeJwt(jwt) {
    try {
      var part = jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
      return JSON.parse(decodeURIComponent(escape(atob(part))));
    } catch (e) {
      return null;
    }
  }

  function showViewer() {
    var claims = decodeJwt(token());
    $('viewerInfo').textContent = claims
      ? 'Viewing as account ' + claims.sub + ' (' + claims.role + (claims.email ? ', ' + claims.email : '') + ')'
      : 'No valid token for party ' + viewer() + ' yet.';
  }

  function loadTokens() {
    $('tokenA').value = STORAGE.getItem('reloop.tracking.tokenA') || '';
    $('tokenB').value = STORAGE.getItem('reloop.tracking.tokenB') || '';
    showViewer();
  }

  function saveTokens() {
    STORAGE.setItem('reloop.tracking.tokenA', $('tokenA').value.trim());
    STORAGE.setItem('reloop.tracking.tokenB', $('tokenB').value.trim());
    showViewer();
    say('Tokens saved for this tab.', 'ok');
  }

  /* ───────────── HTTP ───────────── */

  function call(method, path, body) {
    var headers = { 'Accept': 'application/json' };
    var t = token();
    if (t) { headers['Authorization'] = 'Bearer ' + t; }
    if (body !== undefined) { headers['Content-Type'] = 'application/json'; }
    return fetch(API + path, { method: method, headers: headers, body: body === undefined ? undefined : JSON.stringify(body) })
      .then(function (res) {
        return res.text().then(function (text) {
          var json = null;
          try { json = text ? JSON.parse(text) : null; } catch (e) { json = null; }
          if (!res.ok) {
            var msg = (json && json.message) || res.statusText || 'Request failed';
            if (json && json.fieldErrors) {
              msg += ' — ' + Object.keys(json.fieldErrors).map(function (k) { return k + ' ' + json.fieldErrors[k]; }).join('; ');
            }
            var err = new Error(res.status + ': ' + msg);
            err.status = res.status;
            throw err;
          }
          return json;
        });
      });
  }

  function say(text, kind) {
    var el = $('message');
    el.textContent = text || '';
    el.className = 'message' + (kind ? ' ' + kind : '');
  }

  /* ───────────── map ───────────── */

  function initMap() {
    if (!window.L) {
      $('mapNotice').textContent = 'Leaflet could not be loaded (offline?). Tracking data is still shown below.';
      return;
    }
    map = L.map('map', { scrollWheelZoom: true }).setView([22.4, 71.8], 7);
    L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
    }).addTo(map);

    var label = L.control({ position: 'topright' });
    label.onAdd = function () {
      var div = L.DomUtil.create('div', 'sim-label');
      div.textContent = 'SIMULATED — not GPS';
      return div;
    };
    label.addTo(map);

    layers.demo = L.layerGroup().addTo(map);
    layers.delivery = L.layerGroup().addTo(map);
  }

  function drawDemoLocations(locations) {
    if (!map) { return; }
    layers.demo.clearLayers();
    locations.forEach(function (l) {
      L.circleMarker([l.latitude, l.longitude], { radius: 4, color: '#7a8794', weight: 1, fillOpacity: 0.6 })
        .bindTooltip(l.code + ' — ' + l.label + ', ' + l.city + ' (demo location)')
        .addTo(layers.demo);
    });
  }

  function animateMarker(marker, from, to) {
    if (!from || (from[0] === to[0] && from[1] === to[1])) {
      marker.setLatLng(to);
      return;
    }
    var start = null;
    var duration = 900;
    function frame(ts) {
      if (start === null) { start = ts; }
      var f = Math.min(1, (ts - start) / duration);
      marker.setLatLng([from[0] + (to[0] - from[0]) * f, from[1] + (to[1] - from[1]) * f]);
      if (f < 1) { window.requestAnimationFrame(frame); }
    }
    window.requestAnimationFrame(frame);
  }

  function drawDelivery(d) {
    if (!map) { return; }
    var current = [d.currentPosition.latitude, d.currentPosition.longitude];
    var previous = state.markerPos && state.fitted === d.trackingNumber ? state.markerPos : null;
    layers.delivery.clearLayers();

    L.polyline(d.route, { color: '#5b6773', weight: 3, dashArray: '6 8' })
      .bindTooltip('Approximate straight-line route (simulated)').addTo(layers.delivery);
    var trail = d.history.map(function (p) { return [p.latitude, p.longitude]; });
    L.polyline(trail, { color: '#1f6feb', weight: 5, opacity: 0.8 })
      .bindTooltip('Simulated coordinate history').addTo(layers.delivery);
    d.history.forEach(function (p) {
      L.circleMarker([p.latitude, p.longitude], { radius: 3, color: '#1f6feb', fillOpacity: 1 })
        .bindTooltip('#' + p.sequence + ' ' + p.status + ' — ' + p.note).addTo(layers.delivery);
    });
    L.circleMarker([d.origin.latitude, d.origin.longitude], { radius: 8, color: '#17652e', fillOpacity: 0.8 })
      .bindTooltip('Origin: ' + d.origin.label + ', ' + d.origin.city).addTo(layers.delivery);
    L.circleMarker([d.destination.latitude, d.destination.longitude], { radius: 8, color: '#b42318', fillOpacity: 0.8 })
      .bindTooltip('Destination: ' + d.destination.label + ', ' + d.destination.city).addTo(layers.delivery);

    var marker = L.marker(previous || current, { title: 'Simulated parcel position' })
      .bindTooltip('SIMULATED position · ' + d.statusLabel + ' · ' + d.progressPercent + '%', { permanent: false })
      .addTo(layers.delivery);
    animateMarker(marker, previous, current);
    state.markerPos = current;

    if (state.fitted !== d.trackingNumber) {
      map.fitBounds(L.latLngBounds(d.route).pad(0.25));
      state.fitted = d.trackingNumber;
    }
  }

  /* ───────────── rendering ───────────── */

  function fmt(dt) {
    if (!dt) { return '—'; }
    var date = new Date(dt);
    return isNaN(date.getTime()) ? dt : date.toLocaleString();
  }

  function fact(dl, label, value) {
    var wrap = document.createElement('div');
    var dt = document.createElement('dt');
    var dd = document.createElement('dd');
    dt.textContent = label;
    dd.textContent = value;
    wrap.appendChild(dt);
    wrap.appendChild(dd);
    dl.appendChild(wrap);
  }

  function render(d) {
    state.delivery = d;
    $('tn').textContent = d.trackingNumber;
    $('advanceBtn').disabled = !d.canAdvance;
    $('advanceBtn').textContent = d.canAdvance ? 'Demo: advance to ' + d.nextStatus + ' ▶' : 'Delivered (simulation finished)';

    var stepper = $('stepper');
    stepper.textContent = '';
    var idx = d.statusFlow.indexOf(d.status);
    d.statusFlow.forEach(function (s, i) {
      var li = document.createElement('li');
      li.textContent = s.replace(/_/g, ' ');
      li.className = i < idx ? 'done' : (i === idx ? 'current' : '');
      stepper.appendChild(li);
    });

    var facts = $('facts');
    facts.textContent = '';
    fact(facts, 'Status', d.statusLabel + ' (' + d.progressPercent + '%)');
    fact(facts, 'Type', d.deliveryTypeLabel);
    fact(facts, 'Reference', (d.referenceNumber || '—') + (d.repairRequestId ? ' · repair #' + d.repairRequestId : '')
      + (d.orderId ? ' · order #' + d.orderId : ''));
    fact(facts, 'From', d.origin.label + ', ' + d.origin.city);
    fact(facts, 'To', d.destination.label + ', ' + d.destination.city);
    fact(facts, 'Simulated position', d.currentPosition.latitude.toFixed(5) + ', ' + d.currentPosition.longitude.toFixed(5));
    fact(facts, 'Distance', d.remainingDistanceKm + ' km left of ' + d.routeDistanceKm + ' km (estimate)');
    fact(facts, 'Estimated arrival', fmt(d.estimatedArrivalAt));
    fact(facts, 'Carrier', d.carrier);
    fact(facts, 'Booked', fmt(d.bookedAt));
    fact(facts, 'Picked up', fmt(d.pickedUpAt));
    fact(facts, 'Delivered', fmt(d.deliveredAt));
    fact(facts, 'Notice', d.simulationNotice);

    var body = $('historyBody');
    body.textContent = '';
    d.history.forEach(function (p) {
      var tr = document.createElement('tr');
      [p.sequence, p.status, p.latitude.toFixed(5), p.longitude.toFixed(5), p.progressPercent, p.remainingKm, p.note,
        fmt(p.recordedAt)].forEach(function (v) {
        var td = document.createElement('td');
        td.textContent = String(v);
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });

    drawDelivery(d);
  }

  /* ───────────── actions ───────────── */

  function load(trackingNumber, quiet) {
    if (!trackingNumber) { return Promise.resolve(); }
    return call('GET', 'deliveries/' + encodeURIComponent(trackingNumber))
      .then(function (d) {
        state.trackingNumber = d.trackingNumber;
        $('trackingNumber').value = d.trackingNumber;
        render(d);
        if (!quiet) { say('Loaded ' + d.trackingNumber + ' as party ' + viewer() + '.', 'ok'); }
      })
      .catch(function (e) { say(e.message, 'error'); });
  }

  function advance() {
    if (!state.trackingNumber) { return; }
    $('advanceBtn').disabled = true;
    call('POST', 'deliveries/' + encodeURIComponent(state.trackingNumber) + '/advance')
      .then(function (d) { render(d); say('Simulation advanced to ' + d.status + '.', 'ok'); })
      .catch(function (e) { say(e.message, 'error'); load(state.trackingNumber, true); });
  }

  function book(ev) {
    ev.preventDefault();
    var type = $('deliveryType').value;
    var ref = Number($('refId').value);
    var body = { deliveryType: type };
    if (type === 'STORE_TO_CUSTOMER') { body.orderId = ref; } else { body.repairRequestId = ref; }
    if ($('originCode').value) { body.originCode = $('originCode').value; }
    if ($('destinationCode').value) { body.destinationCode = $('destinationCode').value; }
    call('POST', 'deliveries', body)
      .then(function (d) {
        state.trackingNumber = d.trackingNumber;
        $('trackingNumber').value = d.trackingNumber;
        render(d);
        say('Booked simulated delivery ' + d.trackingNumber + '.', 'ok');
      })
      .catch(function (e) { say(e.message, 'error'); });
  }

  function mine() {
    call('GET', 'deliveries/mine')
      .then(function (list) {
        var ul = $('mineList');
        ul.textContent = '';
        if (!list.length) {
          var empty = document.createElement('li');
          empty.textContent = 'No deliveries for this account yet.';
          ul.appendChild(empty);
        }
        list.forEach(function (s) {
          var li = document.createElement('li');
          li.textContent = s.trackingNumber + ' · ' + s.deliveryType + ' · ' + s.status + ' · ' + s.originCity + ' → '
            + s.destinationCity;
          li.addEventListener('click', function () { load(s.trackingNumber); });
          ul.appendChild(li);
        });
      })
      .catch(function (e) { say(e.message, 'error'); });
  }

  function populateLocations() {
    return call('GET', 'demo-locations')
      .then(function (locations) {
        ['originCode', 'destinationCode'].forEach(function (id) {
          var select = $(id);
          locations.forEach(function (l) {
            var opt = document.createElement('option');
            opt.value = l.code;
            opt.textContent = l.city + ' — ' + l.label;
            select.appendChild(opt);
          });
        });
        drawDemoLocations(locations);
      })
      .catch(function (e) { say('Could not load demo locations: ' + e.message, 'error'); });
  }

  function toggleAutoRefresh() {
    if (state.timer) { window.clearInterval(state.timer); state.timer = null; }
    if ($('autoRefresh').checked) {
      state.timer = window.setInterval(function () { load(state.trackingNumber, true); }, 5000);
    }
  }

  function syncRefLabel() {
    var store = $('deliveryType').value === 'STORE_TO_CUSTOMER';
    $('refLabel').firstChild.textContent = store ? 'Order id ' : 'Repair request id ';
  }

  /* ───────────── wiring ───────────── */

  document.addEventListener('DOMContentLoaded', function () {
    initMap();
    loadTokens();
    populateLocations();
    $('saveTokens').addEventListener('click', saveTokens);
    document.querySelectorAll('input[name=viewer]').forEach(function (r) {
      r.addEventListener('change', function () { showViewer(); load(state.trackingNumber, false); });
    });
    $('bookForm').addEventListener('submit', book);
    $('loadForm').addEventListener('submit', function (ev) { ev.preventDefault(); load($('trackingNumber').value.trim()); });
    $('advanceBtn').addEventListener('click', advance);
    $('mineBtn').addEventListener('click', mine);
    $('autoRefresh').addEventListener('change', toggleAutoRefresh);
    $('deliveryType').addEventListener('change', syncRefLabel);
    var fromUrl = new URLSearchParams(window.location.search).get('tracking');
    if (fromUrl) { load(fromUrl); }
  });
}());
